<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { readScenarioContext, scenarioContextHref } from './scenario-context'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
interface Hit {id:number;sourceId:number;source:string;runId:number;runRef:string;assetId:number;observedAt:string;locator:unknown;category:string;keyId:string;scope:string;version:string;digest:string;current:boolean}
interface Transform {id:number;sourceId:number;source:string;record:string;traceRef:string;spanRef:string;observedAt:string;operation:string;algorithm:string;input:{keyId:string;scope:string;version:string;digest:string};output:{keyId:string;scope:string;version:string;digest:string};current:boolean;evidenceType:string}
interface RuntimeHit {sourceId:number;source:string;service:string;observedAt:string;method:string;route:string;subjectRef?:string;clientIp?:string;locator:string;category:string;record:string}
const context=readScenarioContext(props.workspace.slug)
const token=ref(''),sourceId=ref(''),busy=ref(false),error=ref(''),result=ref<{items:Hit[];runtimeItems?:RuntimeHit[];relations?:Transform[];limit:number;truncated:boolean;coverage:string;warnings:string[]}|null>(null),canQuery=computed(()=>['owner','operator','reviewer'].includes(props.workspace.role));let active:AbortController|undefined
async function search(){if(!canQuery.value)return;active?.abort();active=new AbortController();const signal=active.signal;busy.value=true;error.value='';result.value=null;try{if(token.value.length>4096)throw new Error('查询令牌过长。');const input=JSON.parse(token.value);if(!input||typeof input.keyId!=='string'||typeof input.scope!=='string'||!['utf8_exact_v1','bytes_exact_v1'].includes(input.version)||typeof input.digest!=='string'||!/^\w{64}$/.test(input.digest)||!/^[0-9a-f]{64}$/i.test(input.digest))throw new Error('请粘贴本地CLI生成的keyId、scope、version、digest对象（原值精确文本或密文字节）。');const body={keyId:input.keyId,scope:input.scope,version:input.version,digest:input.digest,...(sourceId.value?{sourceId:Number(sourceId.value)}:{})};result.value=await request(workspacePath(props.workspace.slug)+'/investigations/value-search',{method:'POST',body:JSON.stringify(body),signal})}catch(e){if(!signal.aborted){if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=e instanceof Error&&!(e instanceof ApiError)&&!(e instanceof TypeError)?e.message:describeError(e)}}finally{if(!signal.aborted)busy.value=false}}
onBeforeUnmount(()=>{active?.abort();token.value=''})
</script>
<template><section class="value-search"><div><h2>具体值指纹溯源</h2><p>在客户侧使用HMAC密钥对待查值生成令牌，仅将指纹令牌粘贴到平台。平台不会接收原始值或HMAC密钥。</p></div><p v-if="context.assetId||context.activityId">已保留导航资产{{context.assetId||'未选'}} / 活动{{context.activityId||'未选'}}；查询范围由本地指纹的密钥标识、scope和版本明确限定。</p><p v-if="error" class="message message-error" role="alert">{{error}}</p><form class="panel value-form" @submit.prevent="search"><label>本地CLI生成的查询令牌<textarea v-model="token" rows="5" maxlength="4096" spellcheck="false" placeholder='{"keyId":"…","scope":"…","version":"utf8_exact_v1","digest":"64位十六进制"}' required :disabled="!canQuery"></textarea></label><label>限定文件来源ID（可选）<input v-model="sourceId" type="number" min="1" step="1" :disabled="!canQuery"></label><p>仅查询已记录的同密钥版本、同scope指纹。历史日志未记录指纹的部分仍为未知；无命中不证明没有发生传输。</p><button class="button button-primary" :disabled="busy||!canQuery">{{busy?'正在查询…':'查询已记录指纹'}}</button></form><section v-if="result" class="panel"><div class="panel-heading"><div><h3>文件指纹命中 · {{result.items.length}}条</h3><p>范围：已记录指纹{{result.truncated?'；达到返回上限，请限定来源继续核对':'。'}}历史无指纹日志不在本查询覆盖内。</p></div></div><p v-if="!result.items.length" class="message">当前文件指纹范围没有已记录命中，未采集或未启用指纹的来源保持未知。</p><div v-else class="table-wrap"><table><thead><tr><th>来源 / 运行</th><th>资产</th><th>位置 / 数据标识</th><th>观察时间</th><th>有效性</th></tr></thead><tbody><tr v-for="hit in result.items" :key="hit.id"><td>{{hit.source}}<small>{{hit.runRef}} · #{{hit.runId}}</small></td><td><a :href="scenarioContextHref(workspace.slug,'classification/'+hit.assetId,{assetId:String(hit.assetId)})">资产 #{{hit.assetId}}</a></td><td><code>{{typeof hit.locator==='string'?hit.locator:JSON.stringify(hit.locator)}}</code><small>{{hit.category}}</small></td><td>{{formatDate(hit.observedAt)}}</td><td>{{hit.current?'当前来源观察':'历史记录，需结合新采集'}}</td></tr></tbody></table></div></section><section v-if="result" class="panel"><div class="panel-heading"><div><h3>运行时指纹命中 · {{result.runtimeItems?.length||0}}条</h3><p>与文件命中分开保留来源。填写文件来源ID时，仅查询文件范围。</p></div></div><p v-if="!result.runtimeItems?.length" class="message">当前范围没有已记录运行时指纹命中；未启用指纹的历史观察保持未知。</p><div v-else class="table-wrap"><table><thead><tr><th>来源 / 服务</th><th>实际方法与路由</th><th>主体 / IP</th><th>位置 / 标识</th><th>观察与记录</th></tr></thead><tbody><tr v-for="(hit,index) in result.runtimeItems" :key="index"><td>{{hit.source}}<small>{{hit.service}} · #{{hit.sourceId}}</small></td><td>{{hit.method}} {{hit.route}}</td><td>{{hit.subjectRef||'主体未记录'}}<small>{{hit.clientIp||'IP未记录'}}</small></td><td>{{hit.locator}}<small>{{hit.category}}</small></td><td>{{formatDate(hit.observedAt)}}<small>{{hit.record}}</small></td></tr></tbody></table></div></section><section v-if="result" class="panel"><div class="panel-heading"><div><h3>来源显式登记的加解密关系 · {{result.relations?.length||0}}条</h3><p>仅展示客户侧仪表登记、绑定授权观察记录的匿名输入输出关系；平台未解密数据，不证明数据库加密有效或真实人员身份。</p></div></div><p v-if="!result.relations?.length" class="message">没有命中已登记的加解密转换关系；未采集部分保持未知。</p><div v-else class="table-wrap"><table><thead><tr><th>来源 / 证据</th><th>操作 / 算法</th><th>输入指纹</th><th>输出指纹</th><th>观察</th></tr></thead><tbody><tr v-for="relation in result.relations" :key="relation.id"><td>{{relation.source}}<small>{{relation.record}}</small><small>trace {{relation.traceRef}} / span {{relation.spanRef}}</small></td><td>{{relation.operation==='encrypt'?'加密':relation.operation==='decrypt'?'解密':relation.operation}}<small>{{relation.algorithm}}</small></td><td><details><summary>{{relation.input.keyId}} · {{relation.input.version}}</summary><pre>{{JSON.stringify(relation.input,null,2)}}</pre></details></td><td><details><summary>{{relation.output.keyId}} · {{relation.output.version}}</summary><pre>{{JSON.stringify(relation.output,null,2)}}</pre></details></td><td>{{formatDate(relation.observedAt)}}<small>{{relation.current?'当前授权观察':'历史来源关系'}}</small></td></tr></tbody></table></div></section></section></template>
<style scoped>.value-search{display:grid;gap:18px}.value-search h2{font-size:18px}.value-search h3{font-size:15px}.value-search p{font-size:12px;color:var(--secondary);line-height:1.8}.value-form{padding:20px;display:grid;gap:16px}.value-form label{display:grid;gap:8px;font-size:12px}.value-form textarea,.value-form input{font:inherit;background:var(--surface);color:var(--ink);border:1px solid var(--input-line);border-radius:6px;padding:10px;max-width:100%}.value-form input{max-width:240px}.value-form button{justify-self:start}.value-search table{width:100%;min-width:720px;border-collapse:collapse}.value-search th,.value-search td{text-align:left;font-size:12px;padding:13px;border-bottom:1px solid var(--line);vertical-align:top}.value-search small{display:block;color:var(--secondary);margin-top:5px}.value-search code{overflow-wrap:anywhere}.value-search summary{cursor:pointer;color:var(--accent)}.value-search pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:400px}.value-search a{color:var(--accent)}</style>
